// 统一存放的目标总库
const targetDir = '/data/RunningHub_Project/01_All_Assets';

const today = new Date();
const dateStr = today.toISOString().slice(0, 10).replace(/-/g, '');

const rawItems = $input.all();
const result = [];

for (const item of rawItems) {
  const filePath = item.json.filepath || item.json.path || item.json.filename || '';
  if (!filePath || !/\.(jpg|jpeg|png|webp|gif|bmp)$/i.test(filePath)) continue;

  const fileNameOnly = filePath.split(/[/\\]/).pop();
  const extMatch = fileNameOnly.match(/\.[^.]+$/);
  const ext = extMatch ? extMatch[0] : '.jpg';

  // 1. 匹配人工填写的编号前缀，例如 M001-01 或 M002-03
  const idMatch = fileNameOnly.match(/(M\d{3}-\d{2})/i);

  let newFileName = '';

  if (idMatch) {
    const mainID = idMatch[1].toUpperCase(); // 统一转大写如 M001-01
    const lower = fileNameOnly.toLowerCase();

    // 自动根据文件名里的关键字识别后缀，如果没有关键字则给默认衍生后缀 _UPS
    let tag = '_UPS';
    if (lower.includes('bg') || lower.includes('换背景') || lower.includes('抠图')) {
      tag = '_BG';
    } else if (lower.includes('dress') || lower.includes('换装')) {
      tag = '_DRESS';
    } else if (lower.includes('clr') || lower.includes('高清')) {
      tag = '_CLR';
    }

    newFileName = `${dateStr}-${mainID}${tag}${ext}`;
  } else {
    // 无法识别编号的保底处理
    newFileName = `UNSORTED_${fileNameOnly}`;
  }

  const targetPath = `${targetDir}/${newFileName}`;

  result.push({
    json: {
      originalPath: filePath,
      newFileName: newFileName,
      targetPath: targetPath
    }
  });
}

return result;

